// Independent bank closure using literal path enumeration and exact isomorphism search.
#include <algorithm>
#include <array>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <sstream>
#include <stdexcept>
#include <vector>
using G=std::vector<unsigned>;using I=std::uint64_t;using Pair=std::pair<int,int>;
I path_visits=0,iso_calls=0,iso_nodes=0;
void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
void valid(const G&a){int n=a.size();need(n>0&&n<=15,"safe order");for(int i=0;i<n;++i){need(a[i]<(1u<<n)&&!(a[i]>>i&1),"row");for(int j=0;j<i;++j)need((a[i]>>j&1)+(a[j]>>i&1)==1,"orientation");}}
bool strong(const G&a){int n=a.size();for(int r=0;r<n;++r){unsigned seen=1u<<r,old;do{old=seen;for(int i=0;i<n;++i)if(seen>>i&1)seen|=a[i];}while(old!=seen);if(seen!=(1u<<n)-1)return false;}return true;}
I hp(const G&a,I cap=1000000){I result=0;unsigned full=(1u<<a.size())-1;auto dfs=[&](auto&&self,int last,unsigned used)->void{++path_visits;if(result>cap)return;if(used==full){++result;return;}unsigned next=a[last]&~used;while(next&&result<=cap){unsigned bit=next&-next;next-=bit;self(self,__builtin_ctz(bit),used|bit);}};for(int r=0;r<(int)a.size()&&result<=cap;++r)dfs(dfs,r,1u<<r);return result;}
using Features=std::vector<std::vector<int>>;
Features features(const G&a){int n=a.size();std::vector<int>d(n);for(int i=0;i<n;++i)d[i]=__builtin_popcount(a[i]);Features f(n,std::vector<int>(n+1));for(int i=0;i<n;++i){f[i][0]=d[i];for(int j=0;j<n;++j)if(a[i]>>j&1)++f[i][1+d[j]];}return f;}
std::vector<int> signature(const G&a,int H){auto f=features(a);std::sort(f.begin(),f.end());std::vector<int>key{int(a.size()),H};for(auto&v:f)key.insert(key.end(),v.begin(),v.end());return key;}
bool isomorphic(const G&a,const G&b,bool fixed_root=false){++iso_calls;if(a.size()!=b.size())return false;int n=a.size();auto fa=features(a),fb=features(b);std::vector<int>map(n,-1);unsigned used=0;auto search=[&](auto&&self,int depth)->bool{++iso_nodes;if(depth==n)return true;int v=-1;std::vector<int>best;for(int i=0;i<n;++i)if(map[i]<0){std::vector<int>candidates;for(int j=0;j<n;++j)if(!(used>>j&1)&&fa[i]==fb[j]){bool ok=true;for(int k=0;k<n;++k)if(map[k]>=0&&bool(a[i]>>k&1)!=bool(b[j]>>map[k]&1)){ok=false;break;}if(ok)candidates.push_back(j);}if(candidates.empty())return false;if(v<0||candidates.size()<best.size()){v=i;best=std::move(candidates);}}for(int j:best){map[v]=j;used|=1u<<j;if(self(self,depth+1))return true;used^=1u<<j;map[v]=-1;}return false;};if(fixed_root){map[0]=0;used=1;return search(search,1);}return search(search,0);}
struct Entry{G a;int H;I code;};
struct Profile{I h,s,L;};
Profile profile(const G&a,int root){valid(a);int n=a.size(),N=1<<n,F=N-1;std::vector<I>h(N),e(N),s(N);h[0]=1;auto dfs=[&](auto&&self,int first,int last,unsigned used)->void{++path_visits;++h[used];if(last==root)++e[used];if(first==root)++s[used];unsigned next=a[last]&~used;while(next){unsigned bit=next&-next;next-=bit;self(self,first,__builtin_ctz(bit),used|bit);}};for(int r=0;r<n;++r)dfs(dfs,r,r,1u<<r);I L=0;for(int mask=1;mask<N;++mask)L+=e[mask]*h[F^mask];return{h[F],s[F],L};}
G deletion(const G&a,int skip,int root){std::vector<int>p{root};for(int i=0;i<(int)a.size();++i)if(i!=root&&i!=skip)p.push_back(i);G b(p.size());for(int i=0;i<(int)p.size();++i)for(int j=0;j<(int)p.size();++j)if(a[p[i]]>>p[j]&1)b[i]|=1u<<j;return b;}
G readout(const G&a){G out{2,8,3,5};out.resize(a.size()+3);for(int i=0;i<(int)a.size();++i)for(int j=0;j<(int)a.size();++j)if(a[i]>>j&1)out[i?i+3:0]|=1u<<(j?j+3:0);for(int c=1;c<4;++c)for(int j=1;j<(int)a.size();++j)out[c]|=1u<<(j+3);valid(out);return out;}
std::set<Pair> load_pairs(std::string file){std::ifstream in(file);need(bool(in),"pair file missing");std::set<Pair>r;std::string line;while(std::getline(in,line)){std::istringstream s(line);int B,start;s>>B>>start;need(bool(s),"pair parse");need(r.insert({B,start}).second,"duplicate profile key");}return r;}
int main(){std::ifstream in("BANK153.tsv");need(bool(in),"bank missing");std::vector<Entry>bank;std::vector<std::vector<int>>byorder(11);std::map<std::vector<int>,std::vector<int>>buckets;std::string line;std::vector<int>classcounts(11);while(std::getline(in,line)){std::istringstream ss(line);int n,H;I code;ss>>n>>H>>code;need(n>=3&&n<=10&&H<=153,"bank limits");G a(n);for(auto&x:a)ss>>x;need(bool(ss),"bank parse");valid(a);need(strong(a)&&hp(a,153)==I(H),"literal bank strong/count");I encoded=0;int bit=0;for(int i=0;i<n;++i)for(int j=i+1;j<n;++j,++bit)if(a[i]>>j&1)encoded|=I(1)<<bit;need(encoded==code,"archived upper triangle code");auto sig=signature(a,H);for(int old:buckets[sig])need(!isomorphic(a,bank[old].a),"duplicate isomorphism class");int idx=bank.size();buckets[sig].push_back(idx);byorder[n].push_back(idx);bank.push_back({a,H,code});++classcounts[n];}
 need(bank.size()==1113&&classcounts[3]==1,"bank universe/base");need(isomorphic(bank[byorder[3][0]].a,G{2,4,1}),"triangle base");
 I trials=0,accepted=0;std::vector<I>trials_order(11),accepted_order(11);for(int n=3;n<10;++n){for(int idx:byorder[n]){const G&a=bank[idx].a;for(unsigned mask=1;mask<(1u<<n)-1;++mask){G b=a;b.resize(n+1);for(int i=0;i<n;++i){if(mask>>i&1)b[n]|=1u<<i;else b[i]|=1u<<n;}++trials;++trials_order[n+1];I H=hp(b,153);if(H>153)continue;need(strong(b),"mixed extension strong");auto sig=signature(b,H);auto it=buckets.find(sig);need(it!=buckets.end(),"missing closure bucket");bool found=false;for(int j:it->second)if(isomorphic(b,bank[j].a)){found=true;break;}need(found,"missing qualifying strong extension");++accepted;++accepted_order[n+1];}}std::cerr<<"closure n="<<n+1<<" trials="<<trials_order[n+1]<<" accepted="<<accepted_order[n+1]<<"\n";}
 std::vector<G>rooted_bank;std::map<std::vector<int>,std::vector<int>>rooted_buckets;std::ifstream rf("ROOTED_BANK153.tsv");need(bool(rf),"rooted bank missing");std::set<Pair>rooted_pairs;std::vector<int>rooted_classes(10);while(std::getline(rf,line)){std::istringstream ss(line);int n,B,s;ss>>n>>B>>s;need(n>=3&&n<=9,"rooted order");G a(n);for(auto&x:a)ss>>x;need(bool(ss),"rooted parse");valid(a);need(strong(a),"rooted strong");auto p=profile(a,0);need(p.h+p.L-p.s==I(B)&&p.s==I(s)&&B<=153&&s>=1&&s<=26,"rooted literal profile");auto key=signature(a,p.h);for(int j:rooted_buckets[key])need(!isomorphic(a,rooted_bank[j],true),"duplicate rooted class");rooted_buckets[key].push_back(rooted_bank.size());rooted_bank.push_back(a);rooted_pairs.insert({B,s});++rooted_classes[n];}
 std::set<Pair>strong_profiles;std::set<int>factorcounts;int occurrences=0,occurrences137=0;for(const Entry&z:bank){int n=z.a.size();if(z.H<=26)factorcounts.insert(z.H);for(int a=0;a<n;++a){unsigned incoming=((1u<<n)-1)^(1u<<a)^z.a[a];if(__builtin_popcount(incoming)!=1)continue;int root=__builtin_ctz(incoming);G u=deletion(z.a,a,root);if(!strong(u))continue;auto p=profile(u,0);need(p.h+p.L-p.s==I(z.H),"edge extension inverse identity");if(p.s>=1&&p.s<=26){bool match=false;for(int j:rooted_buckets[signature(u,p.h)])if(isomorphic(u,rooted_bank[j],true)){match=true;break;}need(match,"rooted bank covers every complete edge inverse");strong_profiles.insert({z.H,int(p.s)});++occurrences;if(z.H<=137)++occurrences137;}}}
 need(strong_profiles==load_pairs("STRONG_PROFILES153.tsv")&&strong_profiles==rooted_pairs,"all strong profiles agree");
 std::set<Pair>strong137;for(auto p:strong_profiles)if(p.first<=137)strong137.insert(p);need(strong137==load_pairs("STRONG_PROFILES137.tsv")&&strong137.size()==454&&occurrences137==660,"strong B137 restriction");std::vector<int>classes137(11);std::set<std::tuple<int,int,I>>bank137;for(auto&z:bank)if(z.H<=137){++classes137[z.a.size()];bank137.insert({int(z.a.size()),z.H,z.code});}std::ifstream b137("BANK137.tsv");need(bool(b137),"bank137 missing");std::set<std::tuple<int,int,I>>listed137;while(std::getline(b137,line)){std::istringstream ss(line);int n,H;I code;ss>>n>>H>>code;G a(n);for(auto&x:a)ss>>x;need(bool(ss),"bank137 parse");valid(a);I encoded=0;int bit=0;for(int i=0;i<n;++i)for(int j=i+1;j<n;++j,++bit)if(a[i]>>j&1)encoded|=I(1)<<bit;need(code==encoded&&listed137.insert({n,H,code}).second,"bank137 rows/code");}need(bank137==listed137&&bank137.size()==884,"exact B137 subbank");need(classes137==std::vector<int>({0,0,0,1,1,6,35,321,362,147,11}),"B137 classes by order");need(rooted_classes==std::vector<int>({0,0,0,1,4,24,194,393,167,9}),"rooted classes by order");
 int strong_witnesses=0;std::ifstream sw("STRONG_PROFILES153.tsv");while(std::getline(sw,line)){std::istringstream ss(line);int B,s,n;ss>>B>>s>>n;G a(n);for(auto&x:a)ss>>x;need(bool(ss),"strong witness parse");auto p=profile(a,0);need(strong(a)&&p.h+p.L-p.s==I(B)&&p.s==I(s),"strong stored witness");++strong_witnesses;}need(strong_witnesses==535,"strong witness total");std::set<int>tail{1};bool changed=true;while(changed){changed=false;auto old=tail;for(int x:old)for(int y:factorcounts)if(x*y<=26)changed|=tail.insert(x*y).second;}
 std::set<Pair>all;for(int q:tail){all.insert({q,q});for(auto[B,s]:strong_profiles)if(q*B<=153&&q*s<=26)all.insert({q*B,q*s});}need(all==load_pairs("ALL_PROFILES153.tsv"),"all reduced-tail profiles agree");std::set<Pair>small;for(auto p:all)if(p.first<=137)small.insert(p);need(small==load_pairs("ALL_PROFILES137.tsv")&&small.size()==480,"complete B137 restriction");
 std::array<std::set<int>,2>shifts137;for(int r=1;r<=2;++r)for(int j=0;j<=8;++j)if(small.count({137-2*j,r+3*j}))shifts137[r-1].insert(j);need(shifts137[0]==std::set<int>({1,2,3,5})&&shifts137[1]==std::set<int>({0,3,4,7,8})&&!small.count({137,1}),"complete first-base occupancy");
 std::ifstream wf("ALL_WITNESSES137.tsv");need(bool(wf),"witness file");std::set<Pair>witnessed;int max_order=0;while(std::getline(wf,line)){std::istringstream ss(line);int B,s,n;ss>>B>>s>>n;G a(n);for(auto&v:a)ss>>v;need(bool(ss),"witness parse");auto p=profile(a,0);need(p.s==I(s)&&p.h+p.L-p.s==I(B),"all literal B137 witnesses");need(witnessed.insert({B,s}).second,"duplicate witness pair");max_order=std::max(max_order,n);}need(witnessed==small,"all 480 positive witnesses");
 std::vector<Pair>absent;for(int j=0;j<8;++j){int B=153-2*j,s=1+3*j;need(B>s&&std::gcd(B,s)==1,"gcd reduction");need(!strong_profiles.count({B,s})&&!all.count({B,s}),"F7 absent request");absent.push_back({B,s});}G repair{222,128,2,6,14,31,62,124};auto p=profile(repair,0);need(p.h==77&&p.s==25&&p.L==85&&strong_profiles.count({137,25}),"j8 physical repair");need(hp(readout(repair),500)==461,"literal repaired readout");
 std::cout<<"{\"status\":\"PASS\",\"bank_graphs\":"<<bank.size()<<",\"rooted_bank_graphs\":"<<rooted_bank.size()<<",\"bank137_graphs\":"<<bank137.size()<<",\"strong137_profiles\":"<<strong137.size()<<",\"strong_stored_witnesses\":"<<strong_witnesses<<",\"classes_by_order\":[";for(int n=3;n<=10;++n)std::cout<<(n>3?",":"")<<classcounts[n];std::cout<<"],\"extension_trials\":"<<trials<<",\"qualifying_extensions\":"<<accepted<<",\"exact_isomorphism_calls\":"<<iso_calls<<",\"isomorphism_search_nodes\":"<<iso_nodes<<",\"literal_directed_prefix_visits\":"<<path_visits<<",\"strong_profiles\":"<<strong_profiles.size()<<",\"edge_source_occurrences\":"<<occurrences<<",\"edge_sources_B137\":"<<occurrences137<<",\"all_profiles_B153\":"<<all.size()<<",\"all_profiles_B137\":"<<small.size()<<",\"positive_B137_witnesses\":"<<witnessed.size()<<",\"maximum_B137_witness_order\":"<<max_order<<",\"tail_counts\":[";bool comma=false;for(int q:tail){std::cout<<(comma?",":"")<<q;comma=true;}std::cout<<"],\"absent_requests\":[";for(int i=0;i<8;++i)std::cout<<(i?",":"")<<"["<<absent[i].first<<","<<absent[i].second<<"]";std::cout<<"],\"repair_h_s_L\":[77,25,85],\"repaired_readout_H\":461,\"F7_137\":false,\"F8_137\":\"OPEN\"}\n";
}
